   const r=await api('/api/social/messages?space='+encodeURIComponent(s)+(room?'&room='+encodeURIComponent(room):''));
   if(s!==conversation||!host.isConnected||room!==roomOf())return;
   const key=s+'/'+room;if(host.dataset.key!==key){host.replaceChildren();host.dataset.key=key}
