 function messages(){const list=rooms().filter(s=>s.joined&&matches(nameOf(s)));const selectedRoom=rooms().find(s=>s.id===conversation&&s.joined);return `<div class="soc-message-layout ${selectedRoom?'chat-selected':''}"><aside>${card('Conversations',list.map(s=>B(E(nameOf(s))+((data.notifications||[]).some(n=>n.kind==='message'&&!n.read&&n.target===s.id)?' · New':'')+`<span class="soc-call-flag" data-call-flag="${s.id}" title="Call in progress" ${callActive(s)?'':'hidden'}> · 🔊</span>`,'chat',s.id,s.id===conversation?'active':'')).join('')||empty('No conversations','Message a friend or create a group.'),B('＋ Group','new-chat'))}</aside>${selectedRoom?chatLayout(selectedRoom):empty('Stay in touch','Select a conversation. Direct messages respect the recipient’s privacy settings.',B('Find People','go-people'))}</div>`}
 // Projects: a landing page to pick or start a project, then one workspace per project
