 function taskCard(t,s,finished){const d=t.data,late=overdue(t);return `<article class="soc-task prio-${E(d.priority)}${late?' overdue':''}" data-task="${t.id}"><div class="soc-task-top"><span class="soc-priority ${E(d.priority)}">${E(d.priority)}</span><span class="soc-task-handle" title="Drag to move" aria-hidden="true">⠿</span></div><button type="button" class="soc-task-title" data-social="edit-task" data-id="${t.id}">${E(t.title)}</button><div class="soc-task-meta">${d.checklist.length?`<span>☑ ${d.checklist.filter(x=>x.done).length}/${d.checklist.length}</span>`:''}${d.due?`<span class="${late?'late':''}">⏰ ${E(shortDate(d.due))}${late?' · Overdue':''}</span>`:''}</div>${d.status==='done'&&finished[t.id]?`<p class="soc-task-done">✓ Done by ${E(user(finished[t.id]).name)}</p>`:''}<footer>${d.assigned.length?stack(d.assigned,3):'<small>Unassigned</small>'}<select aria-label="Status for ${E(t.title)}" data-task-status="${t.id}">${lanes(s).map(([v,l])=>`<option value="${v}" ${d.status===v?'selected':''}>${l}</option>`).join('')}</select></footer></article>`}
