 function comingUp(s){const events=(data.events||[]).filter(e=>e.space_id===s.id&&new Date(e.data.end||e.data.start)>=new Date()).sort((a,b)=>a.data.start.localeCompare(b.data.start));return card('📅 Coming up',(events.slice(0,4).map(eventCard).join('')||'<p>No milestones or meetings planned yet.</p>')+`<div class="soc-pj-mini-actions">${B('＋ Milestone','space-milestone',s.id)}${B('＋ Meeting','space-meeting',s.id)}</div>`)}
