 function taskModal(s,t,status){const history=t?s.activity.filter(a=>a.task_id===t.id):[],creator=t?creatorOf(s,t):'';modal(t?'Edit Task':'Add Task',`${F('Task title','title',t?.title||'','text','required maxlength="160"')}${T('Description','description',t?.data.description||'')}${S('Status','status',lanes(s),t?.data.status||status||'todo')}${S('Priority','priority',['low','medium','high','urgent'],t?.data.priority||'medium')}${F('Due date / time','due',t?.data.due||'','datetime-local')}<fieldset><legend>Assign members</legend>${s.members.filter(m=>m.state==='active').map(m=>C(E(user(m.user_id).name),'assigned-'+m.user_id,t?.data.assigned.includes(m.user_id))).join('')}</fieldset>${T('Checklist · one item per line; prefix completed items with [x]','checklist',(t?.data.checklist||[]).map(x=>(x.done?'[x] ':'')+x.text).join('\n'))}<p>Task status is changed explicitly; completing a checklist does not automatically mark the task Done.</p>${t?`<details class="soc-task-history" open><summary>Task history${creator?' · created by '+E(user(creator).name):''}</summary><ol class="soc-log compact">${history.map(a=>logLine(a,true)).join('')||'<li class="soc-log-item"><p>No recorded changes yet.</p></li>'}</ol></details>`:''}${t&&(s.owner===me()||creator===me())?B('Delete task','delete-task',t.id,'soc-danger'):''}`,async(v,f)=>{v.space_id=s.id;v.updated_at=t?.updated_at;v.assigned=[...f.querySelectorAll('[name^=assigned-]:checked')].map(x=>x.name.slice(9));v.checklist=v.checklist.split('\n').filter(x=>x.trim()).map(x=>({text:x.replace(/^\[x\]\s*/i,'').trim(),done:/^\[x\]/i.test(x)}));await write('task',v,t?.id)})}
